(function(){const e=new URLSearchParams(window.location.search).get("XTransformPort");if(!e)return;const i=["/login","/register","/dashboard","/api/auth","/api/household"];function c(r){if(!r)return!1;for(const t of i)if(r===t||r.startsWith(t+"?")||r.startsWith(t+"/"))return!1;return r.charAt(0)==="/"&&r.indexOf("XTransformPort")===-1}document.addEventListener("click",function(r){const t=r.target.closest("a");if(!t)return;const a=t.getAttribute("href");if(c(a)){const o=new URL(a,window.location.origin);o.searchParams.has("XTransformPort")||(o.searchParams.set("XTransformPort",e),t.setAttribute("href",o.pathname+o.search))}})})();const n=new IntersectionObserver(s=>{s.forEach(e=>{e.isIntersecting&&(e.target.classList.add("is-visible"),n.unobserve(e.target))})},{threshold:.1,rootMargin:"0px 0px -50px 0px"});document.querySelectorAll(".reveal").forEach(s=>n.observe(s));
